def total_upto(n):
    total = 0
    for i in range(1, n + 1):
        total += i
    return total

def binary_search(xs, target):
    lo, hi = 0, len(xs) - 1
    while lo <= hi:
        mid = (lo + hi) // 2
        if xs[mid] == target:
            return mid
        elif xs[mid] < target:
            lo = mid + 1
        else:
            hi = mid - 1
    return -1

def merge_sorted(a, b):
    i, j, out = 0, 0, []
    while i < len(a) and j < len(b):
        if a[i] <= b[j]:
            out.append(a[i])
            i += 1
        else:
            out.append(b[j])
            j += 1
    out.extend(a[i:])
    out.extend(b[j:])
    return out

def count_vowels(s):
    vowels = 'aeiouAEIOU'
    n = 0
    for ch in s:
        if ch in vowels:
            n += 1
    return n

def append_item(item, acc=None):
    if acc is None:
        acc = []
    acc.append(item)
    return acc

def is_prime(n):
    if n < 2:
        return False
    r = int(n ** 0.5)
    for d in range(2, r + 1):
        if n % d == 0:
            return False
    return True

def is_sorted(xs):
    for i in range(len(xs) - 1):
        if xs[i] > xs[i + 1]:
            return False
    return True

def deduplicate(xs):
    seen = set()
    out = []
    for x in xs:
        if x not in seen:
            seen.add(x)
            out.append(x)
    return out

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def factorial(n):
    result = 1
    for i in range(2, n + 1):
        result *= i
    return result
